INSERT INTO public.tradition_date_rules (id,tradition_id,calendar_type,month,day,weekday,week_of_month,interval,created_at,updated_at,relative_tradition_id,operations,rule_type,algorithm,frequency) VALUES ('d907f8ed-fdc4-5811-98c8-f2d667696e39', 'c4f0fda5-f0a7-532f-9a5f-a5e52bad00b6', 'gregorian', 0, 1, NULL, NULL, NULL, DEFAULT, DEFAULT, NULL, '{}', 'fixed', NULL, 'yearly'), ('6e5ad56f-8b8e-5504-96f0-ea8871bf9435', '4a425ee8-157c-52d3-9221-c30e5835edd7', 'gregorian', 0, 6, NULL, NULL, NULL, DEFAULT, DEFAULT, NULL, '{}', 'fixed', NULL, 'yearly'), ('359903ea-eb97-5580-8703-5aa3d9210581', '72e9e7e3-831f-51c8-88c4-0e784a800390', 'gregorian', 7, 6, NULL, NULL, NULL, DEFAULT, DEFAULT, NULL, '{}', 'fixed', NULL, 'yearly'), ('24c23cb7-ad13-568d-8982-986bdd2d274b', 'eca7e37f-f6a4-57b2-b924-68be1162f538', 'gregorian', 7, 15, NULL, NULL, NULL, DEFAULT, DEFAULT, NULL, '{}', 'fixed', NULL, 'yearly'), ('40df453e-26c8-5196-a947-b18ba72f8945', '6a42c4dc-3cb8-5301-8998-3fffc5d14479', 'gregorian', 8, 14, NULL, NULL, NULL, DEFAULT, DEFAULT, NULL, '{}', 'fixed', NULL, 'yearly'), ('bcc7ddd0-6b2e-512c-b1b1-5f879f698f96', '9cee602c-5d32-5cab-a1fb-96ad9e1e0f3c', 'gregorian', 9, 31, NULL, NULL, NULL, DEFAULT, DEFAULT, NULL, '{}', 'fixed', NULL, 'yearly'), ('65f5a1fa-48db-510b-83f2-455f7d2aaba6', 'e1ceedfa-14a0-5620-97f6-07bde2e6f569', 'gregorian', 10, 1, NULL, NULL, NULL, DEFAULT, DEFAULT, NULL, '{}', 'fixed', NULL, 'yearly'), ('324db57e-1b00-5c33-a726-aa4d58bb4ef3', '67c187dc-29cc-512c-8bb4-b6edc63706eb', 'gregorian', 10, 1, NULL, NULL, NULL, DEFAULT, DEFAULT, NULL, '{}', 'fixed', NULL, 'yearly');
INSERT INTO public.traditions (id,title,short_description,long_description,created_at,updated_at,visibility,deleted_at,user_id,version) VALUES ('101fd85f-fa79-5e95-981d-efe3bc8f6d9d', 'Palm Sunday', 'The commemoration of Jesus'' triumphal entry into Jerusalem.', 'The [beginning of Holy Week](https://libguides.asu.edu), recalled with the blessing of palm branches to signify the crowds who welcomed Jesus.', DEFAULT, DEFAULT, 'system', '2020-10-06T09:28:26.000Z', NULL, 55449), ('fb6fc016-ef39-58ea-90a9-b5fad9f9cf4d', 'Easter', 'The celebration of the Passion, Death, and Resurrection of Jesus.', 'The [holiest period of the Church year](https://seaportshrine.org), including the Easter Vigil—the first liturgical celebration of the Resurrection—and Easter Sunday.', DEFAULT, DEFAULT, 'system', '2020-03-11T02:50:25.000Z', NULL, 65308), ('3ae7ff55-5de1-5ff2-8f41-914081a8dfcb', 'Feast of the Ascension', 'Celebrates Jesus Christ ascending into heaven.', 'Occurring 40 days after the Resurrection, this feast marks the moment [Jesus ascended bodily into heaven](https://www.christianity.com) in the presence of His apostles.', DEFAULT, DEFAULT, 'system', '2020-09-21T08:58:47.000Z', NULL, 30372), ('f4dc5001-f20d-5d07-aaf6-e4129e82aaf3', 'Pentecost', 'The descent of the Holy Spirit upon the Apostles.', 'Celebrated 50 days after Easter, it commemorates the [Holy Spirit coming to the disciples](https://libguides.asu.edu) as ''tongues of fire,'' marking the birth of the Church.', DEFAULT, DEFAULT, 'system', '2020-01-13T00:51:14.000Z', NULL, 22314), ('53a841fd-e6d8-5d78-87b1-17011b04f2f0', 'Christmas', 'The Nativity of Jesus Christ and the beginning of Christmastide.', 'A major solemnity celebrating the [birth of Jesus Christ](https://www.vaticannews.va) in Bethlehem. It marks the end of Advent and the start of the Christmas season.', DEFAULT, DEFAULT, 'system', '2020-03-19T14:44:08.000Z', NULL, 1419), ('9785d534-ad3a-525c-b5a0-d6ec32bbd360', 'Feast of Corpus Christi', 'The Solemnity of the Most Holy Body and Blood of Christ.', 'A feast honoring the real presence of the [body and blood of Jesus](https://github.com) in the Eucharist, traditionally celebrated after Trinity Sunday.', DEFAULT, DEFAULT, 'system', '2020-05-05T16:21:05.000Z', NULL, 58142), ('9743669d-fd60-5978-9772-81d833b6ee1a', 'First Sunday of Advent', 'The beginning of the liturgical year and a season of preparation.', 'Marks the start of the [Advent season](https://www.usccb.org worship/liturgical-year/advent), a time of expectant waiting and preparation for both the celebration of the Nativity of Christ at Christmas and the return of Christ at the Second Coming.', DEFAULT, DEFAULT, 'system', '2020-09-09T09:01:51.000Z', NULL, 37236), ('216cd372-c28d-5a51-b651-2d62b812e9ba', 'Solemnity of Christ the King', 'Honors Jesus Christ as Lord of all creation.', 'The final Sunday of the [liturgical year](https://www.facebook.com), emphasizing Christ''s sovereignty over the universe.', DEFAULT, DEFAULT, 'system', '2020-04-04T15:52:21.000Z', NULL, 40077), ('d4144788-8f08-5da3-b779-8401ccd69e5a', 'Totensonntag', 'Sunday of the Dead; a German Protestant day of remembrance.', 'The last Sunday before Advent in German Lutheran traditions, dedicated to [remembering those who have died](https://www.christianity.com) in the past year.', DEFAULT, DEFAULT, 'system', '2020-02-06T01:35:28.000Z', NULL, 7588);
